function normalizeRecord(json) {
  if (!json) return null;

  if (Array.isArray(json.records)) {
    return json.records.map(normalizeRecord).filter(Boolean);
  }

  if (json.fields) {
    return {
      id: json.id || json.recordId,
      fields: json.fields,
    };
  }

  const { id, recordId, createdTime, ...rest } = json;

  return {
    id: id || recordId,
    fields: rest,
  };
}

function getRecords(nodeName) {
  const items = $items(nodeName) || [];
  const records = [];

  for (const item of items) {
    const normalized = normalizeRecord(item.json);

    if (Array.isArray(normalized)) {
      records.push(...normalized);
    } else if (normalized) {
      records.push(normalized);
    }
  }

  return records.filter((record) => record.id);
}

function asLinks(value) {
  if (!value) return [];

  if (Array.isArray(value)) {
    return value
      .map((item) => {
        if (typeof item === "string") return item;
        if (item?.id) return item.id;
        if (item?.recordId) return item.recordId;
        return String(item || "");
      })
      .map((item) => item.trim())
      .filter(Boolean);
  }

  if (typeof value === "string") {
    return [value.trim()].filter(Boolean);
  }

  return [];
}

function getString(value) {
  return String(value || "").trim();
}

function normalize(value) {
  return getString(value)
    .toLowerCase()
    .replaceAll("ı", "i")
    .replaceAll("ğ", "g")
    .replaceAll("ü", "u")
    .replaceAll("ş", "s")
    .replaceAll("ö", "o")
    .replaceAll("ç", "c")
    .trim();
}

function isSubmissionDone(submission) {
  const status = normalize(submission.fields.Durum);

  return (
    status === "teslim edildi" ||
    status === "gec teslim" ||
    status === "geç teslim" ||
    status === "degerlendirildi" ||
    status === "değerlendirildi" ||
    submission.fields.Puan !== undefined
  );
}

function formatDate(dateText) {
  if (!dateText) return "-";

  return new Date(dateText).toLocaleDateString("tr-TR", {
    day: "2-digit",
    month: "long",
    year: "numeric",
  });
}

function daysBetween(dateText) {
  if (!dateText) return null;

  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const due = new Date(dateText);
  due.setHours(0, 0, 0, 0);

  const diffMs = due.getTime() - today.getTime();
  return Math.round(diffMs / (1000 * 60 * 60 * 24));
}

function buildEmailHtml({
  studentName,
  assignmentTitle,
  timingText,
  dueDateText,
  trackingCode,
  isOverdue,
}) {
  const statusBg = isOverdue ? "#fef2f2" : "#eff6ff";
  const statusBorder = isOverdue ? "#fecaca" : "#bfdbfe";
  const statusText = isOverdue ? "#7f1d1d" : "#1e3a8a";
  const statusLabel = isOverdue ? "#b91c1c" : "#1d4ed8";

  return `
<div style="font-family:Arial,Helvetica,sans-serif;background:#f1f5f9;padding:32px;">
  <div style="max-width:640px;margin:auto;background:white;border-radius:24px;overflow:hidden;border:1px solid #e2e8f0;">
    <div style="background:#0f172a;color:white;padding:28px 32px;">
      <div style="font-size:12px;letter-spacing:4px;text-transform:uppercase;color:#bfdbfe;font-weight:700;">
        AkıllıSınıf AI
      </div>
      <h1 style="margin:12px 0 0;font-size:28px;line-height:1.2;color:#ffffff;">
        Ödev Teslim Hatırlatması
      </h1>
      <p style="margin:12px 0 0;color:#dbeafe;font-size:15px;line-height:1.6;">
        Bu bildirim n8n otomasyonu tarafından otomatik oluşturulmuştur.
      </p>
    </div>

    <div style="padding:32px;color:#0f172a;">
      <p style="margin:0 0 16px;font-size:16px;line-height:1.7;">
        Merhaba <strong>${studentName}</strong>,
      </p>

      <p style="margin:0 0 20px;font-size:16px;line-height:1.7;">
        <strong>${assignmentTitle}</strong> adlı ödev için
        <strong>${timingText}</strong>.
      </p>

      <div style="margin:22px 0;padding:18px;border-radius:18px;background:#f8fafc;border:1px solid #e2e8f0;">
        <p style="margin:0;color:#64748b;font-size:12px;text-transform:uppercase;font-weight:700;letter-spacing:1px;">
          Teslim Tarihi
        </p>
        <p style="margin:8px 0 0;font-size:20px;font-weight:700;color:#0f172a;">
          ${dueDateText}
        </p>
      </div>

      <div style="margin:22px 0;padding:18px;border-radius:18px;background:${statusBg};border:1px solid ${statusBorder};">
        <p style="margin:0;color:${statusLabel};font-size:12px;text-transform:uppercase;font-weight:700;letter-spacing:1px;">
          Durum
        </p>
        <p style="margin:8px 0 0;font-size:20px;font-weight:700;color:${statusText};">
          ${timingText}
        </p>
      </div>

      <p style="margin:22px 0;font-size:15px;line-height:1.7;color:#475569;">
        Lütfen öğrenci paneline giriş yaparak ödev tesliminizi tamamlayın.
        Teslim ettiğinizi düşünüyorsanız öğretmeninizle iletişime geçebilirsiniz.
      </p>

      <div style="margin-top:28px;padding:16px;border-radius:16px;background:#f8fafc;border:1px solid #e2e8f0;color:#64748b;font-size:12px;line-height:1.6;">
        Sistem takip kodu: ${trackingCode}
      </div>
    </div>

    <div style="background:#f8fafc;padding:20px 32px;border-top:1px solid #e2e8f0;color:#64748b;font-size:12px;line-height:1.6;">
      AkıllıSınıf AI · Yapay Zekâ Destekli Sınıf Performans ve Erken Uyarı Sistemi
    </div>
  </div>
</div>
`;
}

const students = getRecords("GET Students");
const memberships = getRecords("GET Active Memberships");
const assignments = getRecords("GET Active Assignments");
const submissions = getRecords("GET Submissions");
const existingNotifications = getRecords("GET Existing Notifications");

const output = [];

for (const assignment of assignments) {
  const assignmentId = assignment.id;
  const title = getString(assignment.fields.Odev_Basligi) || "Ödev";
  const dueDate = getString(assignment.fields.Teslim_Tarihi);
  const classIds = asLinks(assignment.fields.Sinif);

  if (!dueDate || classIds.length === 0) continue;

  const dayDiff = daysBetween(dueDate);
  const isOverdue = dayDiff !== null && dayDiff < 0;

  let timingText = "teslim tarihi yaklaşıyor";

  if (isOverdue) {
    timingText = "teslim tarihi geçti";
  } else if (dayDiff === 0) {
    timingText = "teslim tarihi bugün";
  } else if (dayDiff === 1) {
    timingText = "teslim tarihi yarın";
  } else if (dayDiff !== null) {
    timingText = `teslim tarihine ${dayDiff} gün kaldı`;
  }

  const activeClassMemberships = memberships.filter((membership) => {
    const membershipClassIds = asLinks(membership.fields.Sinif);
    return membershipClassIds.some((id) => classIds.includes(id));
  });

  for (const membership of activeClassMemberships) {
    const studentId = asLinks(membership.fields.Kullanici)[0];
    const classId = asLinks(membership.fields.Sinif)[0];

    if (!studentId || !classId) continue;

    const student = students.find((item) => item.id === studentId);
    const studentName = getString(student?.fields?.Ad_Soyad) || "Öğrenci";
    const studentEmail = getString(student?.fields?.Eposta);

    if (!studentEmail) continue;

    const alreadySubmitted = submissions.some((submission) => {
      const submissionAssignmentIds = asLinks(submission.fields.Odev);
      const submissionStudentIds = asLinks(submission.fields.Ogrenci);

      return (
        submissionAssignmentIds.includes(assignmentId) &&
        submissionStudentIds.includes(studentId) &&
        isSubmissionDone(submission)
      );
    });

    if (alreadySubmitted) continue;

    const trackingCode = `ODEV:${assignmentId}:ALICI:${studentId}`;

    const duplicateExists = existingNotifications.some((notification) => {
      const message = getString(notification.fields.Mesaj);
      return message.includes(trackingCode);
    });

    if (duplicateExists) continue;

    const dueDateText = formatDate(dueDate);
    const importance = isOverdue ? "Yüksek" : "Orta";

    const message =
      `Merhaba ${studentName}, "${title}" ödevi için ${timingText}. ` +
      `Teslim tarihi: ${dueDateText}. ` +
      `Lütfen öğrenci panelinden ödev tesliminizi tamamlayın.\n\n` +
      `Sistem takip kodu: ${trackingCode}`;

    const emailSubject = isOverdue
      ? `Gecikmiş ödev hatırlatması: ${title}`
      : `Ödev teslim hatırlatması: ${title}`;

    const emailHtml = buildEmailHtml({
      studentName,
      assignmentTitle: title,
      timingText,
      dueDateText,
      trackingCode,
      isOverdue,
    });

    output.push({
      json: {
        emailTo: studentEmail,
        emailSubject,
        emailHtml,
        studentName,
        assignmentTitle: title,
        dueDateText,
        timingText,
        trackingCode,
        fields: {
          Bildirim_Basligi: "Ödev teslim hatırlatması",
          Alici: [studentId],
          Sinif: [classId],
          Bildirim_Turu: "Ödev Hatırlatma",
          Mesaj: message,
          Onem_Derecesi: importance,
          Okundu_Mu: false,
          Gonderildi_Mi: true,
          Kanal: "E-posta + Webhook",
        },
      },
    });
  }
}

return output;
